    "k894": "<a href=\"/models\">{{svg1}}<span>السجل</span></a>",
    "k895": "<a href=\"/institute\">{{svg1}}<span>المعهد</span></a>",
    "k896": "<a href=\"/join\">{{svg1}}<span>الـ 300</span></a>",
